use std::fmt;

/// A point.
#[derive(Debug)]
pub struct Point { x: i32, y: Option<u8> }

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{} {}", self.x, 'c')
    }
}

